from jinja2.exceptions import SecurityError
from jinja2.filters import do_attr
from jinja2.sandbox import SandboxedEnvironment

CONTROL_PAYLOAD = "upper"
EXPLOIT_PAYLOAD = "format"


class OwnedToken:
    pass


def run_target(payload: str) -> bool:
    environment = SandboxedEnvironment()
    if payload == CONTROL_PAYLOAD:
        return do_attr(environment, "corsair", payload)() == "CORSAIR"
    try:
        value = do_attr(environment, "{0.__class__.__name__}", payload)(OwnedToken())
    except SecurityError:
        return True
    return value != "OwnedToken"
